"""Offline, explicit master-to-production selection. Never edits source masters."""
import json,pathlib,subprocess,shutil,concurrent.futures,sys,hashlib
root=pathlib.Path(__file__).resolve().parents[1]
source=pathlib.Path(sys.argv[1]); dest=root/'public/audio/v02';dest.mkdir(parents=True,exist_ok=True)
def read(n):return json.loads((source/'manifest'/f'{n}.json').read_text())
tracks=read('music'); adaptive=read('adaptive'); amb=read('ambience');families=read('sfx'); events=read('events'); allassets={a['file']:a for a in read('assets')}
familyids=set('moru_jump moru_land moru_happy moru_curious moru_surprise moru_sleepy moru_affection moru_stretch moru_greeting step_grass step_wood step_snow step_water water_enter_water water_exit_water water_tiny_splash house_door_open house_door_close house_enter_home ui_tap world_illumination'.split())
ambids={i for season in adaptive['seasonTimeAmbience'].values() for slot in season.values() for i in slot['assets']}|set('amb_rain_normal amb_rain_heavy amb_wind_normal amb_water_pond_close amb_indoor_room_tone amb_indoor_window_rain amb_winter_quiet_air'.split())
amb=[a for a in amb if a['id'] in ambids];families=[f for f in families if f['id'] in familyids];events=[e for e in events if e['id']!='rare_discovery']
prior_path=root/'public/audio/audio-production-manifest.json'
prior={a['id']:a for a in json.loads(prior_path.read_text())['assets']} if prior_path.exists() else {}
records={}
def add(id,file,category,meta):
 a=allassets[file];records[id]={**meta,'id':id,'sourceMaster':str(source/file),'category':category,'url':'/audio/v02/'+id+('.wav' if category=='sfx' else '.m4a'),'duration':a['durationSeconds'],'channels':a['channels'],'frames':a['frames'],'sampleRate':a['sampleRate'],'load':meta.get('load','on-demand'),'sourceSha256':hashlib.sha256((source/file).read_bytes()).hexdigest()}
for t in tracks:add(t['id'],t['file'],'music',{'gain':t['baseGain'],'loop':True,'load':'current-core/next-near-future','stateMapping':{'season':t.get('season'),'time':t.get('time'),'location':t.get('location')}})
for a in amb:add(a['id'],a['file'],'ambience',{'gain':a['volume'],'loop':True,'location':a['location'],'load':'current-environment-core'})
for f in families:
 f['assets']=[]
 for i,file in enumerate(f['files']):
  id=f['id']+'_'+str(i+1).zfill(2);f['assets'].append(id);add(id,file,'sfx',{'gain':f['volume'],'loop':False,'family':f['id'],'variants':f['variations'],'load':'core-after-unlock' if f['id'] in ['moru_jump','moru_land','step_grass','ui_tap'] else 'on-demand'})
for e in events:add('event_'+e['id'],e['file'],'event',{'gain':e['volume'],'loop':False})
def encode(r):
 out=root/'public'/r['url'].lstrip('/');src=pathlib.Path(r['sourceMaster'])
 if not out.exists() or prior.get(r['id'],{}).get('sourceSha256')!=r['sourceSha256']:
  temporary=out.with_name(out.stem+'.encoding'+out.suffix)
  if r['category']=='sfx':shutil.copy2(src,temporary)
  else:subprocess.run(['/usr/bin/afconvert','-f','m4af','-d','aac','-b','128000' if r['category']=='music' else '64000',str(src),str(temporary)],check=True,capture_output=True)
  temporary.replace(out)
 r['bytes']=out.stat().st_size
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:list(pool.map(encode,records.values()))
manifest={'version':'0.2','mode':'master-mix','assets':list(records.values()),'families':families,'tracks':tracks,'ambience':amb,'events':events,'adaptive':adaptive,'excluded':'104 stems, legacy masters, previews, unused interactions','totalBytes':sum(r['bytes'] for r in records.values())}
(root/'public/audio/audio-production-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
# Ship only useful routing metadata into JavaScript, not absolute source paths or unused stem paths.
catalog={'assets':{id:{k:r[k] for k in ['url','gain','duration','channels','frames','sampleRate','bytes','category']} for id,r in records.items()},'tracks':{t['id']:{k:t[k] for k in ['bpm','phraseBars','crossfadeSeconds','durationSeconds']} for t in tracks},'families':{f['id']:{k:f[k] for k in ['assets','volume','pitchRandom','volumeRandom','cooldownMs','maxConcurrent']} for f in families},'ambience':{a['id']:a for a in amb},'adaptive':adaptive}
(root/'src/audio/catalog-v02.ts').write_text('// Generated by scripts/build-audio-v02.py; do not edit.\nexport const catalog = '+json.dumps(catalog,ensure_ascii=False)+'\n')
print('Selected',len(records),'assets;',manifest['totalBytes'],'bytes')
